extern int printf(const char*,...);extern int atoi(const char*);extern int fflush(void*);extern void*calloc(unsigned long,unsigned long);extern void*malloc(unsigned long);typedef unsigned long long U;
int reps[20000],nr=1,inv[5040];int n,N,P[5040][8],pc,perm[8],*mul; int ng=1,L;U groups[20000][80];int gens[20000][12],gc[20000];int ht[131072];int q[5040],vis[5040],stamp;long closures;
void perms(int d,int used){if(d==n){for(int i=0;i<n;i++)P[pc][i]=perm[i];pc++;return;}for(int i=0;i<n;i++)if(!(used>>i&1)){perm[d]=i;perms(d+1,used|(1<<i));}}
int rank(int*p){int r=0;for(int i=0;i<n;i++){int c=0;for(int j=i+1;j<n;j++)c+=p[j]<p[i];r=(n-i)*r+c;}return r;}
int find(U*b){U h=12345;for(int i=0;i<L;i++)h=(h^b[i])*1099511628211ULL;int k=h%131072;while(ht[k]){int g=ht[k]-1,eq=1;for(int i=0;i<L;i++)if(groups[g][i]!=b[i])eq=0;if(eq)return g;k=(k+1)%131072;}ht[k]=ng+1;return -1;}
int np,part[8],types[32][8],nt,typeid[5000];U stab[5000][80];
void partitions(int d,int max){if(d==n){int t[8]={0};for(int i=0;i<n;i++)t[part[i]]++;for(int i=0;i<n;i++)for(int j=0;j<i;j++)if(t[i]>t[j]){int z=t[i];t[i]=t[j];t[j]=z;}int ti;for(ti=0;ti<nt;ti++){int eq=1;for(int i=0;i<n;i++)if(t[i]!=types[ti][i])eq=0;if(eq)break;}if(ti==nt){for(int i=0;i<n;i++)types[nt][i]=t[i];nt++;}typeid[np]=ti;for(int j=0;j<N;j++){int ok=1;for(int i=0;i<n;i++)if(part[i]!=part[P[j][i]])ok=0;if(ok)stab[np][j/64]|=1ULL<<(j%64);}np++;return;}for(int i=0;i<=max+1;i++){part[d]=i;partitions(d+1,i>max?i:max);}}
int main(int argc,char**argv){n=atoi(argv[1]);perms(0,0);N=pc;L=(N+63)/64;mul=malloc(N*N*4UL);for(int i=0;i<N;i++)for(int j=0;j<N;j++){int p[8];for(int k=0;k<n;k++)p[k]=P[i][P[j][k]];mul[i*N+j]=rank(p);}groups[0][0]=1;U b[80]={1};ng=0;find(b);ng=1;
for(int i=0;i<N;i++)for(int j=0;j<N;j++)if(mul[i*N+j]==0){inv[i]=j;break;}for(int rr=0;rr<nr;rr++){int h=reps[rr];for(int g=1;g<N;g++){if(groups[h][g/64]>>(g%64)&1)continue;stamp++;int head=0,tail=1;q[0]=0;vis[0]=stamp;for(int i=0;i<L;i++)b[i]=0;b[0]=1;while(head<tail){int u=q[head++];for(int j=0;j<=gc[h];j++){int z=mul[u*N+(j==gc[h]?g:gens[h][j])];if(vis[z]!=stamp){vis[z]=stamp;q[tail++]=z;b[z/64]|=1ULL<<(z%64);}}}closures++;if(find(b)<0){for(int i=0;i<L;i++)groups[ng][i]=b[i];for(int i=0;i<gc[h];i++)gens[ng][i]=gens[h][i];gens[ng][gc[h]]=g;gc[ng]=gc[h]+1;reps[nr++]=ng;ng++;for(int pp=0;pp<N;pp++){U bc[80]={0};for(int qq=0;qq<tail;qq++){int zz=mul[mul[pp*N+q[qq]]*N+inv[pp]];bc[zz/64]|=1ULL<<(zz%64);}if(find(bc)<0){for(int ii=0;ii<L;ii++)groups[ng][ii]=bc[ii];ng++;}}if(ng==20000){printf("capacity\n");return 1;}}}if(rr%10==0){printf("progress representative=%d groups=%d closures=%ld\n",rr,ng,closures);fflush(0);}}
printf("COMPLETE n=%d N=%d subgroups=%d closures=%ld\n",n,N,ng,closures);part[0]=0;partitions(1,0);U rows[20000];for(int h=0;h<ng;h++){rows[h]=0;for(int j=0;j<np;j++){int ok=1;for(int i=0;i<L;i++){U z=groups[h][i]&stab[j][i];if(i==0)z&=~1ULL;if(z){ok=0;break;}}if(ok)rows[h]|=1ULL<<typeid[j];}}
for(int t=0;t<nt;t++){U ideal=(1ULL<<nt)-1;for(int h=0;h<ng;h++)if(rows[h]>>t&1)ideal&=rows[h];int count=0,wit=-1;for(int h=0;h<ng;h++)if(rows[h]==ideal){count++;wit=h;}printf("partition=");for(int i=0;i<n&&types[t][i];i++)printf("%d,",types[t][i]);printf(" ideal_mask=%llu witnesses=%d group=%d\n",ideal,count,wit);if(!count)printf("COUNTEREXAMPLE\n");}printf("set_partitions=%d types=%d\n",np,nt);}
